struct Node {
    int val;
    Node* next;
    Node(int v) : val(v), next(nullptr) {}   // born pointing nowhere
};

// build 10 -> 20 -> 30 by hand
Node* n1 = new Node(10);
Node* n2 = new Node(20);
Node* n3 = new Node(30);
n1->next = n2;
n2->next = n3;              // n3->next already nullptr
Node* head = n1;

Node* temp = head;                 // never lose head!
while (temp != nullptr) {
    cout << temp->val << " ";
    temp = temp->next;             // hop along the note
}

Node* n = new Node(5);
n->next = head;      // point at OLD first
head = n;            // crown new king
// order matters! head=n first would orphan the list

